type FileLister struct {
	fileHandles       map[string]hostserve.FileHandle
	broker            *plugin.GRPCBroker
	hostServiceClient hostserve.IHostServices
	conn              *grpc.ClientConn
	connMutex         sync.Mutex
}

func (f *FileLister) ListFiles(rootDir, path string) ([]string, error) {
	ctx := context.Background() //this is needed for the host service calls

	// Read Dir
	dirEntries, err := f.hostServiceClient.ReadDir(ctx, rootDir, path)
	if err != nil {
		hclog.Default().Error("Failed to read directory via host service", "root", rootDir, "path", path, "err", err)
		return nil, err
	}

	var entries []string
	var buf bytes.Buffer
	for _, entry := range dirEntries {
		if entry.IsDir() {
			entries = append(entries, entry.Name())
			buf.WriteString(entry.Name())
		} else {
			entries = append(entries, entry.Name())
			buf.WriteString(entry.Name())
		}
	}

	// Write file
	err = f.hostServiceClient.WriteFile(ctx, rootDir, "listed_files.txt", buf.Bytes(), 0644)
	if err != nil {
		hclog.Default().Error("Failed to write file via host service", "dir", rootDir, "err", err)
		return nil, err
	}

	// Open file
	fh, sz, err := f.hostServiceClient.FileOpen(ctx, rootDir, "listed_files.txt", os.O_RDONLY, 0644)
	if err != nil {
		hclog.Default().Error("Failed to open file via host service", "dir", rootDir, "err", err)
	}
	hclog.Default().Info("Opened file", "handle", fh, "size", sz)
	// Close File called in a closure for deferment
	//defer func(hostServiceClient hostserve.IHostServices, ctx context.Context, handle hostserve.FileHandle) {
	//	err := hostServiceClient.FileClose(ctx, handle)
	//	if err != nil {
	//		hclog.Default().Error("Failed to close file handle", "dir", rootDir, "err", err)
	//	}
	//}(f.hostServiceClient, ctx, fh)

	//store the file handle
	f.fileHandles[filepath.Join(rootDir, "listed_files.txt")] = fh

	stream, err := f.hostServiceClient.FileReader(ctx, fh, 64*1024)
	if err != nil {
		hclog.Default().Error("FileRead failed to read file via host service", "root", rootDir, "err", err)
	}
	sb := make([]byte, 10)
	for {
		n, err := stream.Read(sb)
		if err != nil && err != io.EOF {
			hclog.Default().Error("FileRead failed to read file via host service", "root", rootDir, "err", err)
			break
		}
		if n == 0 && err == io.EOF {
			hclog.Default().Info("FileRead reached end of file")
			break
		}
		hclog.Default().Info("FileRead read file", "read", n)
	}

	newFileName := filepath.Join(rootDir, "listed_files.txt")

	fh2, sz2, err := f.hostServiceClient.FileOpen(ctx, rootDir, "listed_files.txt", os.O_RDWR|os.O_CREATE, 0644)
	if err != nil {
		hclog.Default().Error("Failed to open file via host service", "root", rootDir, "err", err)
	}
	hclog.Default().Info("Opened file", "handle", fh2, "size", sz2)

	f.fileHandles[newFileName] = fh2

	//retrieve the file handle
	retrieved, ok := f.fileHandles[newFileName]
	if !ok {
		hclog.Default().Error("Failed to retrieve file handle", "root", rootDir)
	}
	hclog.Default().Info("Retrieved file handle", "handle", retrieved)

	writer, err := f.hostServiceClient.FileWriter(ctx, retrieved)
	if err != nil {
		hclog.Default().Error("Failed to get file writer", "err", err)
	}
	// simulate an actual streaming op
	for i := 0; i < 10; i++ {
		b, err := writer.Write(bunchOfBytes)
		if err != nil {
			hclog.Default().Error("Failed to write to file", "err", err)
		}
		hclog.Default().Info("Wrote to file", "bytes", b)
	}
	err = writer.Close()
	if err != nil {
		return nil, err
	}
	wo := int64(1024)
	writerAt, err := f.hostServiceClient.FileWriterAt(ctx, retrieved, wo)
	if err != nil {
		hclog.Default().Error("Failed to get file writer", "err", err)
	}
	// simulate an actual streaming op
	for i := 0; i < 10; i++ {
		txt := fmt.Sprintf("Wrote to file at offset %d\n", i*1024)
		b, err := writerAt.Write([]byte(txt))
		if err != nil {
			hclog.Default().Error("Failed to write to file", "err", err)
		}
		hclog.Default().Info("Wrote to file", "bytes", b)
	}
	err = writerAt.Close()
	if err != nil {
		return nil, err
	}

	raStream, err := f.hostServiceClient.FileReaderAt(ctx, retrieved, uint64(len(bunchOfBytes)*9), 1024*8)
	if err != nil {
		return nil, err
	}
	rab := make([]byte, 1024*8)
	for {
		n, err := raStream.Read(rab)
		if err != nil && err != io.EOF {
			hclog.Default().Error("FileReadAt failed to read file via host service", "root", rootDir, "err", err)
			break
		}
		if n == 0 && err == io.EOF {
			hclog.Default().Info("FileReadAt reached end of file")
			break
		}
		hclog.Default().Info("FileReadAt read file", "read", n)
	}

	atWrit, err := f.hostServiceClient.FileWriteSection(ctx, retrieved, 1024*4, 50, []byte("Hi Host!"))
	if err != nil {
		return nil, err
	}
	hclog.Default().Info("Wrote to file section", "bytes_written", atWrit)

	err = f.hostServiceClient.FileSync(ctx, retrieved)
	if err != nil {
		hclog.Default().Error("Failed to sync file", "err", err)
	}

	atDat, err := f.hostServiceClient.FileReadSection(ctx, retrieved, 1024*4, int32(atWrit))
	if err != nil {
		hclog.Default().Error("Failed to read file section", "err", err)
	}
	hclog.Default().Info("Read file section", "section", string(atDat))

	err = f.hostServiceClient.FileSync(ctx, fh)
	if err != nil {
		hclog.Default().Error("Failed to sync file", "err", err)
	}

	err = f.hostServiceClient.FileTruncate(ctx, retrieved, 0)
	if err != nil {
		hclog.Default().Error("Failed to truncate file", "err", err)
	}

	err = f.hostServiceClient.Rename(ctx, rootDir, "renameme.md", "rename_works.md")
	if err != nil {
		hclog.Default().Error("Failed to rename file", "err", err)
	}

	err = f.hostServiceClient.Remove(ctx, rootDir, "deleteme.txt")
	if err != nil {
		hclog.Default().Error("Failed to remove file", "err", err)
	}

	// oops we missed closing the file handle -- this showcases the cleanup server-side
	//err = f.hostServiceClient.FileClose(ctx, retrieved)
	//if err != nil {
	//	hclog.Default().Error("Failed to close file handle", "err", err)
	//}

	return entries, nil
}

func (f *FileLister) EstablishHostServices(hostServiceID uint32) (hostserve.ClientID, error) {
	f.connMutex.Lock()
	defer f.connMutex.Unlock()

	conn, err := f.broker.Dial(hostServiceID)
	if err != nil {
		hclog.Default().Error("Failed to dial host service", "err", err)
		return "", fmt.Errorf("failed to dial broker: %w", err)
	}

	f.conn = conn
	client := hostserve.NewHostServiceGRPCClient(hostservev1.NewHostServiceClient(conn))
	f.hostServiceClient = client
	return client.ClientID(), nil
}

func (f *FileLister) DisconnectHostServices() {
	f.connMutex.Lock()
	defer f.connMutex.Unlock()

	if f.conn != nil {
		if err := f.conn.Close(); err != nil {
			hclog.Default().Error("Failed to close connection", "err", err)
		}
		f.conn = nil
		f.hostServiceClient = nil
		hclog.Default().Info("Disconnected from host services")
	}
}

func (f *FileLister) SetBroker(broker *plugin.GRPCBroker) {
	f.broker = broker
}

var handshakeConfig = plugin.HandshakeConfig{
	ProtocolVersion:  1,
	MagicCookieKey:   "TEST_KEY",
	MagicCookieValue: "TEST_VALUE",
}

func main() {
	fl := &FileLister{
		fileHandles: make(map[string]hostserve.FileHandle),
	}

	pluginMap := map[string]plugin.Plugin{
		"fl-plugin": &filelister.FileListerGRPCPlugin{Impl: fl},
	}

	plugin.Serve(&plugin.ServeConfig{
		HandshakeConfig: handshakeConfig,
		Plugins:         pluginMap,
		GRPCServer:      plugin.DefaultGRPCServer,
	})
}
